import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import styles from './ChatWidget.module.css';

const ChatWidget = () => {
  const [open, setOpen] = useState(false);
  const [messages, setMessages] = useState([
    { from: 'manager', text: 'Здравствуйте! Чем могу помочь?' }
  ]);
  const [input, setInput] = useState('');
  const messagesEndRef = useRef(null);

  // Автопрокрутка вниз
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Готовые ответы (имитация менеджера)
  const autoReply = (text) => {
    const lower = text.toLowerCase();
    if (lower.includes('кредит')) return 'Мы можем рассчитать кредит прямо на странице автомобиля. Хотите, я покажу?';
    if (lower.includes('тест') || lower.includes('драйв')) return 'Запись на тест‑драйв доступна после выбора автомобиля. Какую модель вы рассматриваете?';
    if (lower.includes('цена') || lower.includes('стоимость')) return 'Цены указаны в карточках автомобилей. Вам помочь с фильтрацией?';
    if (lower.includes('бмв') || lower.includes('мерседес') || lower.includes('ауди')) return 'Отличный выбор! Давайте посмотрим доступные модели в каталоге.';
    return 'Спасибо за обращение! Наш менеджер свяжется с вами в ближайшее время.';
  };

  const sendMessage = () => {
    if (!input.trim()) return;
    const newUserMsg = { from: 'user', text: input };
    setMessages(prev => [...prev, newUserMsg]);
    setInput('');

    // Имитация ответа менеджера
    setTimeout(() => {
      const reply = autoReply(newUserMsg.text);
      setMessages(prev => [...prev, { from: 'manager', text: reply }]);
    }, 800);
  };

  return (
    <div className={styles.widget}>
      <button className={styles.toggle} onClick={() => setOpen(!open)}>
        {open ? '✕' : '💬'}
      </button>
      <AnimatePresence>
        {open && (
          <motion.div
            className={styles.window}
            initial={{ opacity: 0, scale: 0.9, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.9, y: 20 }}
          >
            <div className={styles.header}>
              <div className={styles.avatar}>К</div>
              <div>
                <div className={styles.name}>Консультант</div>
                <div className={styles.status}>Онлайн</div>
              </div>
            </div>

            <div className={styles.body}>
              {messages.map((msg, idx) => (
                <div
                  key={idx}
                  className={`${styles.msg} ${msg.from === 'user' ? styles.userMsg : styles.managerMsg}`}
                >
                  <div className={styles.bubble}>{msg.text}</div>
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>

            <div className={styles.footer}>
              <input
                type="text"
                placeholder="Напишите сообщение..."
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && sendMessage()}
              />
              <button onClick={sendMessage}>
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M22 2L11 13" /><path d="M22 2L15 22L11 13L2 9L22 2Z" />
                </svg>
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default ChatWidget;
